#[pymethods]
impl Metadata {
    #[allow(clippy::too_many_arguments)]
    #[pyo3(signature = (ocr_used=Self::default().ocr_used, additional=Self::default().additional, title=None, subject=None, authors=None, keywords=None, language=None, created_at=None, modified_at=None, created_by=None, modified_by=None, pages=None, format=None, image_preprocessing=None, json_schema=None, error=None, extraction_duration_ms=None, category=None, tags=None, document_version=None, abstract_text=None, output_format=None))]
    #[new]
    pub fn new(
        ocr_used: bool,
        additional: HashMap<String, String>,
        title: Option<String>,
        subject: Option<String>,
        authors: Option<Vec<String>>,
        keywords: Option<Vec<String>>,
        language: Option<String>,
        created_at: Option<String>,
        modified_at: Option<String>,
        created_by: Option<String>,
        modified_by: Option<String>,
        pages: Option<PageStructure>,
        format: Option<FormatMetadata>,
        image_preprocessing: Option<ImagePreprocessingMetadata>,
        json_schema: Option<String>,
        error: Option<ErrorMetadata>,
        extraction_duration_ms: Option<u64>,
        category: Option<String>,
        tags: Option<Vec<String>>,
        document_version: Option<String>,
        abstract_text: Option<String>,
        output_format: Option<String>,
    ) -> pyo3::PyResult<Self> {
        if let Some(json) = &json_schema {
            serde_json::from_str::<serde_json::Value>(json).map_err(|error| {
                pyo3::exceptions::PyValueError::new_err(format!("invalid JSON in `json_schema`: {error}"))
            })?;
        }
        Ok(Self {
            title,
            subject,
            authors,
            keywords,
            language,
            created_at,
            modified_at,
            created_by,
            modified_by,
            pages,
            format,
            image_preprocessing,
            json_schema,
            error,
            extraction_duration_ms,
            category,
            tags,
            document_version,
            abstract_text,
            output_format,
            ocr_used,
            additional,
        })
    }
}

