#[pymethods]
impl OcrPipelineStage {
    #[allow(clippy::too_many_arguments)]
    #[pyo3(signature = (backend, priority, language=None, paddle_ocr_config=None, paddle_ocr_settings=None, vlm_config=None, backend_options=None))]
    #[new]
    pub fn new(
        backend: String,
        priority: u32,
        language: Option<Vec<String>>,
        paddle_ocr_config: Option<String>,
        paddle_ocr_settings: Option<PaddleOcrConfig>,
        vlm_config: Option<LlmConfig>,
        backend_options: Option<String>,
    ) -> pyo3::PyResult<Self> {
        if let Some(json) = &paddle_ocr_config {
            serde_json::from_str::<serde_json::Value>(json).map_err(|error| {
                pyo3::exceptions::PyValueError::new_err(format!("invalid JSON in `paddle_ocr_config`: {error}"))
            })?;
        }
        if let Some(json) = &backend_options {
            serde_json::from_str::<serde_json::Value>(json).map_err(|error| {
                pyo3::exceptions::PyValueError::new_err(format!("invalid JSON in `backend_options`: {error}"))
            })?;
        }
        Ok(Self {
            backend,
            priority,
            language,
            paddle_ocr_config,
            paddle_ocr_settings,
            vlm_config,
            backend_options,
        })
    }
}

