#[serde(rename_all = "snake_case")]
#[pyclass(eq, eq_int, from_py_object)]
pub enum ElementType {
    #[pyo3(name = "TITLE")]
    #[default]
    Title = 0,
    #[pyo3(name = "NARRATIVE_TEXT")]
    NarrativeText = 1,
    #[pyo3(name = "HEADING")]
    Heading = 2,
    #[pyo3(name = "LIST_ITEM")]
    ListItem = 3,
    #[pyo3(name = "TABLE")]
    Table = 4,
    #[pyo3(name = "IMAGE")]
    Image = 5,
    #[pyo3(name = "PAGE_BREAK")]
    PageBreak = 6,
    #[pyo3(name = "CODE_BLOCK")]
    CodeBlock = 7,
    #[pyo3(name = "FORMULA")]
    Formula = 8,
    #[pyo3(name = "BLOCK_QUOTE")]
    BlockQuote = 9,
    #[pyo3(name = "FOOTER")]
    Footer = 10,
    #[pyo3(name = "HEADER")]
    Header = 11,
}
#[pymethods]
impl ElementType {
    // eq_int compares the discriminant, so Python hashing must use the same integer.
    fn __hash__(&self) -> isize {
        self.clone() as isize
    }

    #[new]
    fn __new__(value: pyo3::Bound<'_, pyo3::PyAny>) -> pyo3::PyResult<Self> {
        use pyo3::prelude::*;
        // Try to extract as string first
        if let Ok(s) = value.extract::<&str>() {
            let s_lower = s.to_lowercase();
            match s_lower.as_str() {
                "title" => return Ok(Self::Title),
                "narrativetext" => return Ok(Self::NarrativeText),
                "narrative_text" => return Ok(Self::NarrativeText),
                "heading" => return Ok(Self::Heading),
                "listitem" => return Ok(Self::ListItem),
                "list_item" => return Ok(Self::ListItem),
                "table" => return Ok(Self::Table),
                "image" => return Ok(Self::Image),
                "pagebreak" => return Ok(Self::PageBreak),
                "page_break" => return Ok(Self::PageBreak),
                "codeblock" => return Ok(Self::CodeBlock),
                "code_block" => return Ok(Self::CodeBlock),
                "formula" => return Ok(Self::Formula),
                "blockquote" => return Ok(Self::BlockQuote),
                "block_quote" => return Ok(Self::BlockQuote),
                "footer" => return Ok(Self::Footer),
                "header" => return Ok(Self::Header),
                _ => {}
            }
        }
        // Try to extract as integer (by discriminant value)
        if let Ok(n) = value.extract::<i32>() {
            match n {
                0 => return Ok(Self::Title),
                1 => return Ok(Self::NarrativeText),
                2 => return Ok(Self::Heading),
                3 => return Ok(Self::ListItem),
                4 => return Ok(Self::Table),
                5 => return Ok(Self::Image),
                6 => return Ok(Self::PageBreak),
                7 => return Ok(Self::CodeBlock),
                8 => return Ok(Self::Formula),
                9 => return Ok(Self::BlockQuote),
                10 => return Ok(Self::Footer),
                11 => return Ok(Self::Header),
                _ => {}
            }
        }
        let type_name = stringify!(ElementType);
        Err(pyo3::exceptions::PyValueError::new_err(format!(
            "invalid value for {}: {:#?}. Expected variant name (str) or discriminant (int)",
            type_name, value
        )))
    }

    fn __str__(&self) -> PyResult<String> {
        serde_json::to_value(self)
            .map(|value| match value {
                serde_json::Value::String(value) => value,
                other => other.to_string(),
            })
            .map_err(|e| pyo3::exceptions::PyRuntimeError::new_err(format!("Failed to serialize ElementType: {e}")))
    }

    fn __repr__(&self) -> PyResult<String> {
        self.__str__()
    }
}

